import { useId } from 'react';
import { BRAND } from '@hms/shared';
import { cn } from '@/lib/utils';

/**
 * Medophelp mark — same geometry as branding/logo/medophelp-mark.svg (generated by
 * tools/brand/build-brand.mjs): gradient tile, heartbeat "M", medical cross.
 */
export function BrandMark({ className, reversed = false, title = BRAND.name }: { className?: string; reversed?: boolean; title?: string }) {
  const id = useId().replace(/:/g, '');
  const fg = reversed ? BRAND.colors.blue : '#FFFFFF';
  return (
    <svg viewBox="0 0 64 64" className={cn('h-8 w-8 shrink-0', className)} role={title ? 'img' : undefined} aria-label={title || undefined} aria-hidden={title ? undefined : true}>
      <defs>
        <linearGradient id={`mp-${id}`} x1="0" y1="0" x2="64" y2="64" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor={BRAND.colors.blue} />
          <stop offset="1" stopColor={BRAND.colors.teal} />
        </linearGradient>
      </defs>
      <rect width="64" height="64" rx="16" fill={reversed ? '#FFFFFF' : `url(#mp-${id})`} />
      <polyline points="10,41 19,41 24.5,23 32,39 39.5,23 45,41 54,41" fill="none" stroke={fg} strokeWidth="5" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M48.5 9.5h3v4h4v3h-4v4h-3v-4h-4v-3h4z" fill={fg} />
    </svg>
  );
}

/** Mark + "Medophelp" wordmark, optionally with the brand line. */
export function BrandLogo({
  className,
  markClassName,
  tagline = false,
  tone = 'default',
  size = 'md',
}: {
  className?: string;
  markClassName?: string;
  tagline?: boolean;
  /** `light` for dark backgrounds (sidebar, login panel). */
  tone?: 'default' | 'light';
  size?: 'md' | 'lg';
}) {
  return (
    <span className={cn('flex min-w-0 items-center gap-2.5', className)}>
      <BrandMark className={markClassName} title="" />
      <span className="min-w-0">
        <span className={cn('block truncate font-display font-extrabold leading-tight tracking-tight', size === 'lg' ? 'text-xl' : 'text-base', tone === 'light' ? 'text-white' : 'text-fg')}>{BRAND.name}</span>
        {tagline && <span className={cn('block truncate leading-tight', size === 'lg' ? 'text-xs' : 'text-[11px]', tone === 'light' ? 'text-white/75' : 'text-muted')}>{BRAND.tagline}</span>}
      </span>
    </span>
  );
}
